package com.jarvis.os.core.context.rule

import android.util.Log
import com.jarvis.os.core.context.model.ContextState
import com.jarvis.os.core.context.model.MotionType
import com.jarvis.os.core.context.model.SemanticLocation

/**
 * Action generated by rule engine when a context condition triggers.
 */
sealed class ContextAction {
    data class SetVolumeMode(val silent: Boolean, val vibrate: Boolean) : ContextAction()
    data class ReadNotificationsAloud(val enabled: Boolean) : ContextAction()
    data class EnableAutoReply(val message: String) : ContextAction()
    data class LaunchAppSuggestion(val packageName: String, val appName: String) : ContextAction()
    data class ShowNotificationReminders(val title: String, val body: String) : ContextAction()
    data class SuggestBatterySaver(val enable: Boolean) : ContextAction()
}

/**
 * Single evaluation rule interface.
 */
interface ContextRule {
    val ruleId: String
    fun evaluate(state: ContextState): List<ContextAction>
}

/**
 * Modular Rule Engine that evaluates the current unified ContextState
 * against active rules to produce proactive actions.
 */
class RuleEngine {

    companion object {
        private const val TAG = "JarvisRuleEngine"
    }

    private val rules = mutableListOf<ContextRule>()

    init {
        // Register default production rules
        registerRule(CollegeStudyRule())
        registerRule(DrivingSafetyRule())
        registerRule(LowBatteryRule())
        registerRule(HeadphoneMusicRule())
    }

    fun registerRule(rule: ContextRule) {
        rules.add(rule)
        Log.i(TAG, "Registered context rule: ${rule.ruleId}")
    }

    fun evaluate(state: ContextState): List<ContextAction> {
        val actions = mutableListOf<ContextAction>()
        for (rule in rules) {
            try {
                val result = rule.evaluate(state)
                if (result.isNotEmpty()) {
                    Log.i(TAG, "Rule '${rule.ruleId}' triggered ${result.size} actions")
                    actions.addAll(result)
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error evaluating rule '${rule.ruleId}'", e)
            }
        }
        return actions
    }
}

// ── Rule 1: College / Study Rule ──
class CollegeStudyRule : ContextRule {
    override val ruleId: String = "COLLEGE_STUDY_RULE"

    override fun evaluate(state: ContextState): List<ContextAction> {
        if (state.location.semanticLocation == SemanticLocation.COLLEGE) {
            return listOf(
                ContextAction.SetVolumeMode(silent = true, vibrate = true),
                ContextAction.ShowNotificationReminders(
                    title = "College Mode Active",
                    body = "Phone set to Silent. Tap to view today's timetable & assignments."
                )
            )
        }
        return emptyList()
    }
}

// ── Rule 2: Driving Safety Rule ──
class DrivingSafetyRule : ContextRule {
    override val ruleId: String = "DRIVING_SAFETY_RULE"

    override fun evaluate(state: ContextState): List<ContextAction> {
        if (state.motion.type == MotionType.DRIVING || state.audio.isCarBluetoothConnected) {
            return listOf(
                ContextAction.ReadNotificationsAloud(enabled = true),
                ContextAction.EnableAutoReply("I'm driving right now. JARVIS will relay your message when safe."),
                ContextAction.LaunchAppSuggestion("com.google.android.apps.maps", "Google Maps")
            )
        }
        return emptyList()
    }
}

// ── Rule 3: Low Battery Rule ──
class LowBatteryRule : ContextRule {
    override val ruleId: String = "LOW_BATTERY_RULE"

    override fun evaluate(state: ContextState): List<ContextAction> {
        if (state.battery.levelPercentage < 15 && !state.battery.isCharging) {
            return listOf(
                ContextAction.SuggestBatterySaver(enable = true),
                ContextAction.ShowNotificationReminders(
                    title = "Low Battery Warning (15%)",
                    body = "JARVIS has throttled background AI activity to preserve battery life."
                )
            )
        }
        return emptyList()
    }
}

// ── Rule 4: Headphone Music Rule ──
class HeadphoneMusicRule : ContextRule {
    override val ruleId: String = "HEADPHONE_MUSIC_RULE"

    override fun evaluate(state: ContextState): List<ContextAction> {
        if (state.audio.isHeadphonesConnected) {
            return listOf(
                ContextAction.LaunchAppSuggestion("com.google.android.youtube", "YouTube Music")
            )
        }
        return emptyList()
    }
}
